import{_ as t,c as o,o as c,ah as n}from"./chunks/framework.CdwlI3v5.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"_layout":"writeup","ctf":"nullcon HackIM 2019","chal":"GeniuneCounterMode","flag":"hackim19{forb1dd3n_made_e4sy_a7gh12}","points":462,"category":"crypto"},"headers":[],"relativePath":"writeups/2019/nullcon/GenuineCounterMode/2019-02-02-GenuineCounterMode.md","filePath":"writeups/2019/nullcon/GenuineCounterMode/2019-02-02-GenuineCounterMode.md"}'),a={name:"writeups/2019/nullcon/GenuineCounterMode/2019-02-02-GenuineCounterMode.md"};function d(i,e,s,r,p,l){return c(),o("div",null,[...e[0]||(e[0]=[n('<blockquote><p>server runs on</p></blockquote><blockquote><p>nc crypto.ctf.nullcon.net 5000</p></blockquote><blockquote><p>can you get the flag?</p></blockquote><p>We are given a <a href="./server.py">server.py</a>.</p><p>This challenge wants us to forge a message that is encoded with AES CTR, and there&#39;s a MAC code(GHASH)</p><h2 id="aes-ctr-forging" tabindex="-1">AES CTR forging <a class="header-anchor" href="#aes-ctr-forging" aria-label="Permalink to “AES CTR forging”">​</a></h2><p>AES CTR is relatively simple to forge, given a plaintext(pt) and a ciphertext(ct), if the nonce is the same, <code>pt^ct</code> is always constant.</p><h2 id="ghash" tabindex="-1">GHASH <a class="header-anchor" href="#ghash" aria-label="Permalink to “GHASH”">​</a></h2><p>GHASH function is a pseudo-hashing function.</p><p>First it calculates</p><p><code>c = AES.new(key, AES.MODE_ECB).encrypt(nonce + bytes(3) + b&#39;\\x01&#39;)</code></p><p><code>H = AES.new(key, AES.MODE_ECB).encrypt(bytes(16))</code></p><p>and splits the ciphertext into blocks of 128 bits(<code>b1,b2,b3...</code>)</p><p>The GHASH is then calculated by <code>c+b1H^1+b2H^2+...+bnH^n</code> where <code>n</code> is the number of blocks and each of the summand is under <code>mod n</code></p><p>c constant for a fixed nonce, and H is constant throughout, this suggests a nonce reuse attack. Luckily the nonce is calculated using <code>sessionid + Random.get_random_bytes(2)</code>, so nonce reuse will be very common.</p><h2 id="calculating-c-and-h" tabindex="-1">Calculating c and H <a class="header-anchor" href="#calculating-c-and-h" aria-label="Permalink to “Calculating c and H”">​</a></h2><p>Since we need to forge 2 blocks in the final payload, our payload should be 2 blocks</p><p>First we find 2 plaintext-ciphertext pairs with the same nonce, we label them as <code>pt11+pt12</code>,<code>pt21+pt22</code> and <code>ct11+ct12</code>,<code>ct21+ct22</code>(where <code>xxx1</code> is the first block and <code>xxx2</code> is the second block), and the respective GHASH as <code>g1</code>,<code>g2</code>.</p><p>The GASHes in terms of the pt,ct,c,H are :</p><p><code>g1=c+ct11*H+ct12*H**2</code><code>g2=c+ct21*H+ct22*H**2</code></p><p>Supposing <code>ct12=ct22</code>(equivalent to <code>pt11=pt12</code>), <code>c</code> and <code>H</code> can easily be found:</p><p><code>g1-g2=ct11*H-ct21*H</code><code>H=(g1-g2)/(ct11-ct21) (mod n)</code><code>c=g1-ct11*H-ct12*H**2 (mod n)</code></p><h2 id="forging" tabindex="-1">Forging <a class="header-anchor" href="#forging" aria-label="Permalink to “Forging”">​</a></h2><p>Forging is now very simple. The text we want to forge is <code>f=&quot;may i please have the flag&quot;</code></p><p>Let the nonce be the nonce that was repeated(so that we know what c is)</p><p>The ciphertext is simply <code>pt11^f^ct11</code></p><p>GASH is <code>c+f1*H+f2*H**2</code> where <code>f1</code> is the first 16 characters/128 bits</p><p>Full exploit: <a href="./solve.py">solve.py</a></p><p>p.s. A much simpler way of getting c is literally xoring the last block of the ciphertext with the plaintext, since <code>c=AESECB(k,nonce+&#39;\\x00\\x00\\x00\\x01)</code> and the first plaintext is xored with the exact same value</p>',29)])])}const g=t(a,[["render",d]]);export{u as __pageData,g as default};
